BEGIN;
-- Negative user knowledge is distinct from matching results and source availability.
CREATE TABLE track_provider_exclusion (
 track_id TEXT NOT NULL REFERENCES track(id) ON DELETE CASCADE,
 provider TEXT NOT NULL,
 declared_at INTEGER NOT NULL DEFAULT(unixepoch()),
 PRIMARY KEY(track_id,provider)
) STRICT;
CREATE INDEX provider_exclusion_list ON track_provider_exclusion(provider,track_id);
ALTER TABLE spotify_connection_review ADD COLUMN evaluation_version INTEGER NOT NULL DEFAULT 0;
ALTER TABLE spotify_connection_review ADD COLUMN stale INTEGER NOT NULL DEFAULT 1 CHECK(stale IN(0,1));
ALTER TABLE spotify_connection_review ADD COLUMN state TEXT NOT NULL DEFAULT 'unresolved' CHECK(state IN('unresolved','needs_retry'));
CREATE INDEX spotify_review_stale ON spotify_connection_review(stale,track_id);
CREATE INDEX spotify_review_version ON spotify_connection_review(evaluation_version,track_id);
CREATE TABLE spotify_reconciliation_cache (
 track_id TEXT PRIMARY KEY REFERENCES track(id) ON DELETE CASCADE,
 input_json TEXT NOT NULL CHECK(json_valid(input_json)),
 page_json TEXT NOT NULL CHECK(json_valid(page_json))
) STRICT;
CREATE TABLE spotify_program_cache (
 album_id TEXT PRIMARY KEY REFERENCES album(id) ON DELETE CASCADE,
 programs_json TEXT NOT NULL CHECK(json_valid(programs_json))
) STRICT;
CREATE TRIGGER spotify_exclusion_unconnected BEFORE INSERT ON track_provider_exclusion
WHEN NEW.provider='spotify' AND EXISTS(SELECT 1 FROM trusted_spotify_track WHERE track_id=NEW.track_id)
BEGIN SELECT RAISE(ABORT,'Connected Track cannot be marked not on Spotify'); END;
CREATE TRIGGER lifecycle_track_provider_evidence_insert AFTER INSERT ON track_provider_evidence BEGIN
UPDATE spotify_connection_review SET stale=1 WHERE stale=0 AND track_id IN(SELECT t.id FROM track t JOIN release r ON r.id=t.release_id WHERE r.album_id IN(SELECT r2.album_id FROM track t2 JOIN release r2 ON r2.id=t2.release_id WHERE t2.id=NEW.track_id)) AND NOT EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=spotify_connection_review.track_id) AND NOT EXISTS(SELECT 1 FROM track_provider_exclusion x WHERE x.track_id=spotify_connection_review.track_id AND x.provider='spotify');
END;
