CREATE TRIGGER lifecycle_connected_track_external_identity_insert AFTER INSERT ON track_external_identity WHEN NEW.provider='spotify' AND EXISTS(SELECT 1 FROM trusted_spotify_track WHERE track_id=NEW.track_id) BEGIN DELETE FROM track_provider_exclusion WHERE track_id=NEW.track_id AND provider='spotify'; UPDATE spotify_connection_review SET stale=0,evaluation_version=2 WHERE track_id=NEW.track_id; END;
