CREATE TRIGGER lifecycle_connected_manual_track_association_insert AFTER INSERT ON manual_track_association WHEN NEW.album_provider='spotify' AND EXISTS(SELECT 1 FROM trusted_spotify_track WHERE track_id=NEW.track_id) BEGIN DELETE FROM track_provider_exclusion WHERE track_id=NEW.track_id AND provider='spotify'; UPDATE spotify_connection_review SET stale=0,evaluation_version=2 WHERE track_id=NEW.track_id; END;
CREATE TRIGGER lifecycle_connected_manual_track_association_update AFTER UPDATE ON manual_track_association WHEN NEW.album_provider='spotify' AND EXISTS(SELECT 1 FROM trusted_spotify_track WHERE track_id=NEW.track_id) BEGIN DELETE FROM track_provider_exclusion WHERE track_id=NEW.track_id AND provider='spotify'; UPDATE spotify_connection_review SET stale=0,evaluation_version=2 WHERE track_id=NEW.track_id; END;
CREATE TRIGGER lifecycle_connected_provider_track_association_insert AFTER INSERT ON provider_track_association WHEN NEW.album_provider='spotify' AND EXISTS(SELECT 1 FROM trusted_spotify_track WHERE track_id=NEW.track_id) BEGIN DELETE FROM track_provider_exclusion WHERE track_id=NEW.track_id AND provider='spotify'; UPDATE spotify_connection_review SET stale=0,evaluation_version=2 WHERE track_id=NEW.track_id; END;
CREATE TRIGGER lifecycle_connected_provider_track_association_update AFTER UPDATE ON provider_track_association WHEN NEW.album_provider='spotify' AND EXISTS(SELECT 1 FROM trusted_spotify_track WHERE track_id=NEW.track_id) BEGIN DELETE FROM track_provider_exclusion WHERE track_id=NEW.track_id AND provider='spotify'; UPDATE spotify_connection_review SET stale=0,evaluation_version=2 WHERE track_id=NEW.track_id; END;
-- Existing successful associations need no upgrade work; only review bookkeeping changes.
UPDATE spotify_connection_review SET evaluation_version=2,stale=0 WHERE EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=spotify_connection_review.track_id);
CREATE TRIGGER spotify_exclusion_update_unconnected BEFORE UPDATE ON track_provider_exclusion
WHEN NEW.provider='spotify' AND EXISTS(SELECT 1 FROM trusted_spotify_track WHERE track_id=NEW.track_id)
BEGIN SELECT RAISE(ABORT,'Connected Track cannot be marked not on Spotify'); END;
CREATE TRIGGER lifecycle_exclusion_added AFTER INSERT ON track_provider_exclusion WHEN NEW.provider='spotify' BEGIN
 UPDATE spotify_connection_review SET stale=0,evaluation_version=2 WHERE track_id=NEW.track_id;
END;
CREATE TRIGGER lifecycle_exclusion_removed AFTER DELETE ON track_provider_exclusion WHEN OLD.provider='spotify' BEGIN
 UPDATE spotify_connection_review SET stale=1 WHERE track_id=OLD.track_id;
END;
CREATE TRIGGER lifecycle_album_identity_connected_insert AFTER INSERT ON album_external_identity WHEN NEW.provider='spotify' BEGIN
 DELETE FROM track_provider_exclusion WHERE provider='spotify' AND track_id IN(SELECT t.id FROM track t JOIN release r ON r.id=t.release_id WHERE r.album_id=NEW.album_id) AND EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=track_provider_exclusion.track_id);
END;
CREATE TRIGGER lifecycle_album_identity_connected_update AFTER UPDATE ON album_external_identity WHEN NEW.provider='spotify' BEGIN
 DELETE FROM track_provider_exclusion WHERE provider='spotify' AND track_id IN(SELECT t.id FROM track t JOIN release r ON r.id=t.release_id WHERE r.album_id=NEW.album_id) AND EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=track_provider_exclusion.track_id);
END;
CREATE TRIGGER lifecycle_manual_track_association_removed AFTER DELETE ON manual_track_association WHEN OLD.album_provider='spotify' BEGIN
 UPDATE spotify_connection_review SET stale=1 WHERE track_id=OLD.track_id AND NOT EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=OLD.track_id);
END;
CREATE TRIGGER lifecycle_provider_track_association_removed AFTER DELETE ON provider_track_association WHEN OLD.album_provider='spotify' BEGIN
 UPDATE spotify_connection_review SET stale=1 WHERE track_id=OLD.track_id AND NOT EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=OLD.track_id);
END;
CREATE TRIGGER lifecycle_recording_identity_insert AFTER INSERT ON recording_external_identity BEGIN
UPDATE spotify_connection_review SET stale=1 WHERE stale=0 AND track_id IN(SELECT t.id FROM track t JOIN release r ON r.id=t.release_id WHERE r.album_id IN(SELECT r2.album_id FROM track t2 JOIN release r2 ON r2.id=t2.release_id WHERE t2.recording_id=NEW.recording_id)) AND NOT EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=spotify_connection_review.track_id) AND NOT EXISTS(SELECT 1 FROM track_provider_exclusion x WHERE x.track_id=spotify_connection_review.track_id AND x.provider='spotify');
END;
CREATE TRIGGER lifecycle_recording_identity_update AFTER UPDATE ON recording_external_identity BEGIN
UPDATE spotify_connection_review SET stale=1 WHERE stale=0 AND track_id IN(SELECT t.id FROM track t JOIN release r ON r.id=t.release_id WHERE r.album_id IN(SELECT r2.album_id FROM track t2 JOIN release r2 ON r2.id=t2.release_id WHERE t2.recording_id=OLD.recording_id)) AND NOT EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=spotify_connection_review.track_id) AND NOT EXISTS(SELECT 1 FROM track_provider_exclusion x WHERE x.track_id=spotify_connection_review.track_id AND x.provider='spotify');
UPDATE spotify_connection_review SET stale=1 WHERE stale=0 AND track_id IN(SELECT t.id FROM track t JOIN release r ON r.id=t.release_id WHERE r.album_id IN(SELECT r2.album_id FROM track t2 JOIN release r2 ON r2.id=t2.release_id WHERE t2.recording_id=NEW.recording_id)) AND NOT EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=spotify_connection_review.track_id) AND NOT EXISTS(SELECT 1 FROM track_provider_exclusion x WHERE x.track_id=spotify_connection_review.track_id AND x.provider='spotify');
END;
CREATE TRIGGER lifecycle_recording_identity_delete AFTER DELETE ON recording_external_identity BEGIN
UPDATE spotify_connection_review SET stale=1 WHERE stale=0 AND track_id IN(SELECT t.id FROM track t JOIN release r ON r.id=t.release_id WHERE r.album_id IN(SELECT r2.album_id FROM track t2 JOIN release r2 ON r2.id=t2.release_id WHERE t2.recording_id=OLD.recording_id)) AND NOT EXISTS(SELECT 1 FROM trusted_spotify_track s WHERE s.track_id=spotify_connection_review.track_id) AND NOT EXISTS(SELECT 1 FROM track_provider_exclusion x WHERE x.track_id=spotify_connection_review.track_id AND x.provider='spotify');
END;
PRAGMA user_version=29;
COMMIT;
